import { ImageIcon } from "lucide-react";

function ImagePlaceholder() {
  return (
    <div className="w-full aspect-square rounded-lg border border-dashed border-stone-300 bg-stone-100 flex items-center justify-center">
      <ImageIcon size={40} className="text-stone-400" />
    </div>
  );
}

export default function Interview() {
  return (
    <div className="max-w-3xl mx-auto px-6 py-16">
      <h1 className="text-3xl font-semibold text-stone-900 mb-10 text-center">Interview</h1>

      <div className="grid grid-cols-2 gap-10">
        {/* Left — Start interview */}
        <div className="flex flex-col items-center gap-4">
          <ImagePlaceholder />
          <button className="flex items-center gap-2 px-4 h-10 rounded-md text-sm font-medium bg-stone-900 text-white hover:bg-stone-800 transition-colors">
            Start interview
          </button>
        </div>

        {/* Right — View resume analysis */}
        <div className="flex flex-col items-center gap-4">
          <ImagePlaceholder />
          <button className="flex items-center gap-2 px-4 h-10 rounded-md text-sm font-medium bg-stone-900 text-white hover:bg-stone-800 transition-colors">
            View resume analysis
          </button>
        </div>
      </div>
    </div>
  );
}
